#include <vector>
#include <cstddef>
#include <cmath>
#include <omp.h>

struct COOElement {
   size_t row, column;
   double value;
};

/* Solve the sparse linear system Ax=b for x.
   A is a sparse NxN matrix in COO format. x and b are dense vectors with N elements.
   Uses a parallel Jacobi iteration (robust for any OpenMP thread count).
*/
void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    x.assign(N, 0.0);
    if (N == 0) return;

    // Build diagonal D and split A into off-diagonals for Jacobi.
    std::vector<double> D(N, 0.0);
    std::vector<COOElement> off;
    off.reserve(A.size());

    for (const auto& e : A) {
        if (e.row >= N || e.column >= N) continue; // ignore invalid entries
        if (e.row == e.column) D[e.row] += e.value; // sum duplicates on diagonal
        else off.push_back(e);
    }

    // Detect singular/near-singular diagonal.
    const double diag_eps = 1e-14;
    for (size_t i = 0; i < N; ++i) {
        if (std::fabs(D[i]) <= diag_eps) {
            // Cannot safely do Jacobi without a usable diagonal; return current x (zeros).
            return;
        }
    }

    std::vector<double> xnew(N, 0.0);

    // Parameters: modest defaults; caller can refine by wrapping / editing as needed.
    const int maxIters = 2000;
    const double tol = 1e-10;

    for (int it = 0; it < maxIters; ++it) {
        // y = b - (A_off * x)
        std::vector<double> y = b;

        // Each thread accumulates into a private buffer to avoid concurrent writes to y.
        const int T = omp_get_max_threads();
        std::vector<std::vector<double>> ypriv(T, std::vector<double>(N, 0.0));

        #pragma omp parallel
        {
            const int tid = omp_get_thread_num();
            auto &local = ypriv[tid];

            #pragma omp for schedule(static)
            for (std::ptrdiff_t k = 0; k < static_cast<std::ptrdiff_t>(off.size()); ++k) {
                const auto &e = off[static_cast<size_t>(k)];
                // local contribution: -(a_ij * x_j) to row i
                local[e.row] -= e.value * x[e.column];
            }
        }

        // Reduce private buffers into y (single-threaded reduction to keep it simple/correct).
        for (int t = 0; t < T; ++t) {
            const auto &local = ypriv[t];
            for (size_t i = 0; i < N; ++i) y[i] += local[i];
        }

        // xnew = y / D, and compute max update for convergence.
        double maxDiff = 0.0;
        #pragma omp parallel for reduction(max:maxDiff) schedule(static)
        for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(N); ++i) {
            const size_t ii = static_cast<size_t>(i);
            const double xi = y[ii] / D[ii];
            xnew[ii] = xi;
            const double d = std::fabs(xi - x[ii]);
            if (d > maxDiff) maxDiff = d;
        }

        x.swap(xnew);

        if (maxDiff < tol) break;
    }
}
